#include "auto_animation/rigging/BoneRecognition.hpp"
#include <cctype>
namespace auto_animation::rigging{namespace{std::string n(std::string s){for(char&c:s){c=(char)std::tolower((unsigned char)c);if(c=='_'||c=='-'||c=='.'||c==':')c=' ';}return s;}}std::vector<BoneMatch>recognize_bones(const Skeleton&s){struct R{const char*c;const char*a;};constexpr R rs[]={{"root","root"},{"pelvis","pelvis"},{"spine","spine"},{"chest","chest"},{"neck","neck"},{"head","head"},{"left_arm","leftarm larm upperarm arm l"},{"right_arm","rightarm rarm upperarm arm r"},{"left_forearm","leftforearm lforearm lowerarm forearm"},{"right_forearm","rightforearm rforearm lowerarm forearm"},{"left_hand","lefthand lhand"},{"right_hand","righthand rhand"},{"left_thigh","leftthigh lthigh thigh l"},{"right_thigh","rightthigh rthigh thigh r"},{"left_calf","leftcalf lcalf shin l"},{"right_calf","rightcalf rcalf shin r"},{"left_foot","leftfoot lfoot foot l"},{"right_foot","rightfoot rfoot foot r"},{"tail","tail tailroot"},{"jaw","jaw mandible"},{"wing_left","leftwing wing l"},{"wing_right","rightwing wing r"}};std::vector<BoneMatch>o;for(int i=0;i<(int)s.bones.size();++i){auto x=n(s.bones[i].name);float best=0;const char*can=nullptr;for(auto&r:rs){auto a=n(r.a);if(x==a){best=1;can=r.c;break;}if(x.find(a)!=std::string::npos&&best<.7f){best=.7f;can=r.c;}}if(can)o.push_back({i,can,best});}return o;}}